-- Increment 7B milestone 2: recipient-bound workspace invitations.
-- Tokens are generated by Postgres and only their SHA-256 digest is stored.

create table public.workspace_invitations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  recipient_email text not null check (recipient_email = lower(btrim(recipient_email)) and recipient_email like '%@%'),
  role_code text not null check (role_code in ('administrator','assigner','umpire','league_viewer')),
  token_digest bytea not null unique,
  invited_by_auth_user_id uuid not null references auth.users(id) on delete restrict,
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  expired_at timestamptz,
  accepted_at timestamptz,
  accepted_by_auth_user_id uuid references auth.users(id) on delete restrict,
  regeneration_count integer not null default 0 check (regeneration_count between 0 and 10),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id,id),
  check (expires_at > issued_at),
  check ((accepted_at is null) = (accepted_by_auth_user_id is null)),
  check (accepted_at is null or (revoked_at is null and expired_at is null))
);

create unique index workspace_invitations_pending_recipient_idx
  on public.workspace_invitations(organization_id,recipient_email)
  where accepted_at is null and revoked_at is null and expired_at is null;
create index workspace_invitations_workspace_status_idx
  on public.workspace_invitations(organization_id,issued_at desc);
create index workspace_invitations_inviter_rate_idx
  on public.workspace_invitations(invited_by_auth_user_id,issued_at desc);

create trigger workspace_invitations_set_updated_at
before update on public.workspace_invitations
for each row execute function public.set_updated_at();

alter table public.workspace_invitations enable row level security;
create policy workspace_invitations_no_direct_access
on public.workspace_invitations for all to authenticated
using (false) with check (false);
revoke all on table public.workspace_invitations from public,anon,authenticated;

create or replace function private.workspace_invitation_role_allowed(
  p_organization_id uuid,p_role_code text
) returns boolean
language sql stable security definer
set search_path=pg_catalog,public
as $$
  select case p_role_code
    when 'administrator' then true
    when 'assigner' then private.organization_module_enabled(p_organization_id,'umpire')
    when 'umpire' then private.organization_module_enabled(p_organization_id,'umpire')
    when 'league_viewer' then private.organization_module_enabled(p_organization_id,'league')
    else false
  end
$$;

create or replace function private.assert_workspace_invitation_administrator()
returns uuid
language plpgsql stable security definer
set search_path=pg_catalog,public
as $$
declare v_organization_id uuid := public.current_organization_id();
begin
  if (select auth.uid()) is null or v_organization_id is null then
    raise exception using errcode='42501',message='workspace_context_required';
  end if;
  if not private.has_membership_role(v_organization_id,array['administrator']) then
    raise exception using errcode='42501',message='workspace_administrator_required';
  end if;
  return v_organization_id;
end;
$$;

create or replace function public.issue_workspace_invitation(
  p_recipient_email text,p_role_code text,p_expires_in_hours integer default 72
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,extensions,public,auth
as $$
declare
  v_organization_id uuid := private.assert_workspace_invitation_administrator();
  v_actor uuid := (select auth.uid());
  v_email text := lower(btrim(coalesce(p_recipient_email,'')));
  v_token text;
  v_row public.workspace_invitations%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor::text,1));
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='P0001',message='invitation_email_invalid';
  end if;
  if p_expires_in_hours is null or p_expires_in_hours < 1 or p_expires_in_hours > 168 then
    raise exception using errcode='P0001',message='invitation_expiration_invalid';
  end if;
  if not private.workspace_invitation_role_allowed(v_organization_id,p_role_code) then
    raise exception using errcode='42501',message='invitation_role_not_enabled';
  end if;
  if exists(select 1 from auth.users where id=v_actor and lower(email)=v_email) then
    raise exception using errcode='42501',message='invitation_self_forbidden';
  end if;
  if exists(
    select 1 from public.organization_memberships m join auth.users u on u.id=m.auth_user_id
    where m.organization_id=v_organization_id and lower(u.email)=v_email
  ) then
    raise exception using errcode='P0001',message='invitation_membership_exists';
  end if;
  if exists(
    select 1 from public.workspace_invitations i
    where i.organization_id=v_organization_id and i.recipient_email=v_email
      and i.accepted_at is null and i.revoked_at is null and i.expired_at is null and i.expires_at>now()
  ) then
    raise exception using errcode='P0001',message='invitation_pending_exists';
  end if;
  if (select count(*) from public.workspace_invitations where invited_by_auth_user_id=v_actor and issued_at>now()-interval '10 minutes') >= 3
     or (select count(*) from public.workspace_invitations where organization_id=v_organization_id and issued_at>now()-interval '1 day') >= 20 then
    raise exception using errcode='42501',message='invitation_rate_limited';
  end if;

  v_token := encode(extensions.gen_random_bytes(32),'hex');
  insert into public.workspace_invitations(
    organization_id,recipient_email,role_code,token_digest,invited_by_auth_user_id,expires_at
  ) values (
    v_organization_id,v_email,p_role_code,
    extensions.digest(convert_to(v_token,'utf8'),'sha256'),v_actor,
    now()+make_interval(hours=>p_expires_in_hours)
  ) returning * into v_row;

  insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
  values(v_organization_id,v_actor,'workspace.invitation_issued','workspace_invitation',v_row.id,
    jsonb_build_object('role',p_role_code,'expires_at',v_row.expires_at));

  return jsonb_build_object('invitation_id',v_row.id,'token',v_token,'expires_at',v_row.expires_at);
exception when unique_violation then
  raise exception using errcode='P0001',message='invitation_pending_exists';
end;
$$;

create or replace function public.get_workspace_invitations()
returns table(
  invitation_id uuid,recipient_email text,role_code text,status text,
  issued_at timestamptz,expires_at timestamptz,accepted_at timestamptz,
  revoked_at timestamptz,regeneration_count integer
)
language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare v_organization_id uuid := private.assert_workspace_invitation_administrator();
begin
  with newly_expired as (
    update public.workspace_invitations i set expired_at=now()
    where i.organization_id=v_organization_id and i.accepted_at is null
      and i.revoked_at is null and i.expired_at is null and i.expires_at<=now()
    returning i.id,i.role_code
  )
  insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
  select v_organization_id,(select auth.uid()),'workspace.invitation_expired','workspace_invitation',id,
    jsonb_build_object('role',role_code) from newly_expired;

  return query select i.id,i.recipient_email,i.role_code,
    case when i.accepted_at is not null then 'accepted'
         when i.revoked_at is not null then 'revoked'
         when i.expired_at is not null or i.expires_at<=now() then 'expired'
         else 'pending' end,
    i.issued_at,i.expires_at,i.accepted_at,i.revoked_at,i.regeneration_count
  from public.workspace_invitations i
  where i.organization_id=v_organization_id
  order by i.issued_at desc,i.id;
end;
$$;

create or replace function public.preview_workspace_invitation(p_token text)
returns jsonb
language plpgsql stable security definer
set search_path=pg_catalog,extensions,public,auth
as $$
declare
  v_actor uuid := (select auth.uid());
  v_user auth.users%rowtype;
  v_invitation public.workspace_invitations%rowtype;
  v_organization_name text;
begin
  if v_actor is null then raise exception using errcode='42501',message='authentication_required'; end if;
  select * into v_user from auth.users where id=v_actor;
  if not found or v_user.email_confirmed_at is null then
    raise exception using errcode='42501',message='verified_email_required';
  end if;
  if length(coalesce(p_token,''))<>64 then return jsonb_build_object('valid',false,'code','invitation_invalid'); end if;
  select * into v_invitation from public.workspace_invitations
  where token_digest=extensions.digest(convert_to(p_token,'utf8'),'sha256');
  if not found then return jsonb_build_object('valid',false,'code','invitation_invalid'); end if;
  if v_invitation.accepted_at is not null then return jsonb_build_object('valid',false,'code','invitation_already_accepted'); end if;
  if v_invitation.revoked_at is not null then return jsonb_build_object('valid',false,'code','invitation_revoked'); end if;
  if v_invitation.expired_at is not null or v_invitation.expires_at<=now() then return jsonb_build_object('valid',false,'code','invitation_expired'); end if;
  if lower(v_user.email)<>v_invitation.recipient_email then return jsonb_build_object('valid',false,'code','invitation_recipient_mismatch'); end if;
  select name into v_organization_name from public.organizations where id=v_invitation.organization_id and active;
  if not found then return jsonb_build_object('valid',false,'code','invitation_workspace_unavailable'); end if;
  return jsonb_build_object('valid',true,'organization_name',v_organization_name,
    'role',v_invitation.role_code,'expires_at',v_invitation.expires_at);
end;
$$;

create or replace function public.revoke_workspace_invitation(p_invitation_id uuid)
returns boolean
language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare
  v_organization_id uuid := private.assert_workspace_invitation_administrator();
  v_actor uuid := (select auth.uid());
  v_row public.workspace_invitations%rowtype;
begin
  select * into v_row from public.workspace_invitations
  where id=p_invitation_id and organization_id=v_organization_id for update;
  if not found then raise exception using errcode='P0001',message='invitation_not_found'; end if;
  if v_row.accepted_at is not null then raise exception using errcode='P0001',message='invitation_already_accepted'; end if;
  if v_row.revoked_at is not null then return true; end if;
  update public.workspace_invitations set revoked_at=now() where id=v_row.id;
  insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
  values(v_organization_id,v_actor,'workspace.invitation_revoked','workspace_invitation',v_row.id,
    jsonb_build_object('role',v_row.role_code));
  return true;
end;
$$;

create or replace function public.regenerate_workspace_invitation(
  p_invitation_id uuid,p_expires_in_hours integer default 72
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,extensions,public
as $$
declare
  v_organization_id uuid := private.assert_workspace_invitation_administrator();
  v_actor uuid := (select auth.uid());
  v_token text;
  v_row public.workspace_invitations%rowtype;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor::text,1));
  if p_expires_in_hours is null or p_expires_in_hours<1 or p_expires_in_hours>168 then
    raise exception using errcode='P0001',message='invitation_expiration_invalid';
  end if;
  select * into v_row from public.workspace_invitations
  where id=p_invitation_id and organization_id=v_organization_id for update;
  if not found then raise exception using errcode='P0001',message='invitation_not_found'; end if;
  if v_row.accepted_at is not null then raise exception using errcode='P0001',message='invitation_already_accepted'; end if;
  if v_row.regeneration_count>=10 then raise exception using errcode='42501',message='invitation_regeneration_limit_reached'; end if;
  if (select count(*) from public.workspace_invitations where invited_by_auth_user_id=v_actor and issued_at>now()-interval '10 minutes') >= 3 then
    raise exception using errcode='42501',message='invitation_rate_limited';
  end if;
  v_token:=encode(extensions.gen_random_bytes(32),'hex');
  update public.workspace_invitations set
    token_digest=extensions.digest(convert_to(v_token,'utf8'),'sha256'),
    invited_by_auth_user_id=v_actor,issued_at=now(),expires_at=now()+make_interval(hours=>p_expires_in_hours),
    revoked_at=null,expired_at=null,regeneration_count=regeneration_count+1
  where id=v_row.id returning * into v_row;
  insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
  values(v_organization_id,v_actor,'workspace.invitation_regenerated','workspace_invitation',v_row.id,
    jsonb_build_object('role',v_row.role_code,'expires_at',v_row.expires_at,'generation',v_row.regeneration_count));
  return jsonb_build_object('invitation_id',v_row.id,'token',v_token,'expires_at',v_row.expires_at);
end;
$$;

create or replace function public.accept_workspace_invitation(p_token text)
returns jsonb
language plpgsql security definer
set search_path=pg_catalog,extensions,public,auth
as $$
declare
  v_actor uuid := (select auth.uid());
  v_user auth.users%rowtype;
  v_invitation public.workspace_invitations%rowtype;
  v_source public.profiles%rowtype;
  v_profile_id uuid;
  v_membership_id uuid;
begin
  if v_actor is null then raise exception using errcode='42501',message='authentication_required'; end if;
  select * into v_user from auth.users where id=v_actor;
  if not found or v_user.email_confirmed_at is null then
    raise exception using errcode='42501',message='verified_email_required';
  end if;
  if length(coalesce(p_token,''))<>64 then
    return jsonb_build_object('accepted',false,'code','invitation_invalid');
  end if;
  select * into v_invitation from public.workspace_invitations
  where token_digest=extensions.digest(convert_to(p_token,'utf8'),'sha256') for update;
  if not found then return jsonb_build_object('accepted',false,'code','invitation_invalid'); end if;
  if v_invitation.accepted_at is not null then return jsonb_build_object('accepted',false,'code','invitation_already_accepted'); end if;
  if v_invitation.revoked_at is not null then return jsonb_build_object('accepted',false,'code','invitation_revoked'); end if;
  if v_invitation.expired_at is not null or v_invitation.expires_at<=now() then
    if v_invitation.expired_at is null then
      update public.workspace_invitations set expired_at=now() where id=v_invitation.id;
      insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
      values(v_invitation.organization_id,v_actor,'workspace.invitation_expired','workspace_invitation',v_invitation.id,
        jsonb_build_object('role',v_invitation.role_code));
    end if;
    return jsonb_build_object('accepted',false,'code','invitation_expired');
  end if;
  if lower(v_user.email)<>v_invitation.recipient_email then
    return jsonb_build_object('accepted',false,'code','invitation_recipient_mismatch');
  end if;
  if exists(select 1 from public.organization_memberships where organization_id=v_invitation.organization_id and auth_user_id=v_actor) then
    return jsonb_build_object('accepted',false,'code','invitation_membership_exists');
  end if;

  select * into v_source from public.profiles where auth_user_id=v_actor
  order by (status='approved') desc,created_at,id limit 1;
  insert into public.profiles(
    organization_id,auth_user_id,role,status,first_name,last_name,email,phone,home_phone,address,
    contact_preference,emergency_contact,emergency_contact_phone,communication_preferences,approved_at
  ) values (
    v_invitation.organization_id,v_actor,v_invitation.role_code::public.account_role,'approved',
    coalesce(nullif(v_source.first_name,''),nullif(v_user.raw_user_meta_data->>'first_name',''),'Invited'),
    coalesce(nullif(v_source.last_name,''),nullif(v_user.raw_user_meta_data->>'last_name',''),'User'),
    lower(v_user.email),coalesce(v_source.phone,''),coalesce(v_source.home_phone,''),coalesce(v_source.address,''),
    coalesce(v_source.contact_preference,'text'),coalesce(v_source.emergency_contact,''),
    coalesce(v_source.emergency_contact_phone,''),coalesce(v_source.communication_preferences,'{}'::jsonb),now()
  ) returning id into v_profile_id;
  if v_invitation.role_code='umpire' then
    insert into public.crew_members(organization_id,profile_id,first_name,last_name,email,phone,active)
    select v_invitation.organization_id,v_profile_id,p.first_name,p.last_name,p.email,p.phone,true
    from public.profiles p where p.id=v_profile_id;
  end if;
  select id into strict v_membership_id from public.organization_memberships
  where organization_id=v_invitation.organization_id and auth_user_id=v_actor and profile_id=v_profile_id and status='approved';
  update public.workspace_invitations set accepted_at=now(),accepted_by_auth_user_id=v_actor where id=v_invitation.id;
  insert into public.user_workspace_contexts(auth_user_id,organization_id,membership_id,selected_at,last_validated_at)
  values(v_actor,v_invitation.organization_id,v_membership_id,now(),now())
  on conflict(auth_user_id) do update set organization_id=excluded.organization_id,
    membership_id=excluded.membership_id,selected_at=excluded.selected_at,last_validated_at=excluded.last_validated_at;
  insert into public.workspace_audit_events(organization_id,actor_auth_user_id,action,entity_type,entity_id,metadata)
  values(v_invitation.organization_id,v_actor,'workspace.invitation_accepted','workspace_invitation',v_invitation.id,
    jsonb_build_object('role',v_invitation.role_code,'profile_id',v_profile_id,'membership_id',v_membership_id));
  return jsonb_build_object('accepted',true,'organization_id',v_invitation.organization_id,
    'membership_id',v_membership_id,'profile_id',v_profile_id,'role',v_invitation.role_code);
end;
$$;

revoke all on function private.workspace_invitation_role_allowed(uuid,text) from public,anon,authenticated;
revoke all on function private.assert_workspace_invitation_administrator() from public,anon,authenticated;
revoke all on function public.issue_workspace_invitation(text,text,integer) from public,anon,authenticated;
revoke all on function public.get_workspace_invitations() from public,anon,authenticated;
revoke all on function public.preview_workspace_invitation(text) from public,anon,authenticated;
revoke all on function public.revoke_workspace_invitation(uuid) from public,anon,authenticated;
revoke all on function public.regenerate_workspace_invitation(uuid,integer) from public,anon,authenticated;
revoke all on function public.accept_workspace_invitation(text) from public,anon,authenticated;
grant execute on function public.issue_workspace_invitation(text,text,integer) to authenticated;
grant execute on function public.get_workspace_invitations() to authenticated;
grant execute on function public.preview_workspace_invitation(text) to authenticated;
grant execute on function public.revoke_workspace_invitation(uuid) to authenticated;
grant execute on function public.regenerate_workspace_invitation(uuid,integer) to authenticated;
grant execute on function public.accept_workspace_invitation(text) to authenticated;

comment on table public.workspace_invitations is 'RPC-owned, recipient-bound workspace invitations. Token plaintext is never stored.';
comment on function public.accept_workspace_invitation(text) is 'Accepts only a one-use token; workspace, recipient, and role come exclusively from the locked server record.';
